figure.sourcecode:
wexp-core-record = { protocol: tstr, protocol_version: tstr, record_id: tstr, created_at: tdate, event: event-block, subject: subject-block, model: model-block, witness: witness-block, seal: seal-block, disclosure: disclosure-block, ? capabilities_ref: tstr, ; reference to published CC capabilities ? input: input-block, ; required at WL1 and WL2 ? execution: execution-block, ; required at WL3 ? evidence: evidence-block, ; top-level evidence only ? extensions: extensions-map, }
; claimed_level encoding (ratified): string form WL = "WL0" / "WL1" / "WL2" / "WL3" / "WL4" / "WL5" ; Comparison semantics (informative): "WLn" maps to integer n for the ; honesty invariants. The verified level is bounded by ; min( claimed, attainable(boundary_type, claimed, evidence), ; maxCapability(CC), recorder_ceiling, chain_min ) ; Implementations MUST parse "WLn" as integer n for ordering ; comparisons, then re-encode as string in records.
; Hash-alg identifier; "sha-256" is the default. Each hash field ; carries its own algorithm so the record is self-describing. hash-alg = "sha-256" / tstr
; All octet strings in JSON serialization (seal.sig, *_hash, digest) ; are encoded as base64url WITHOUT padding.
event-block = { operation: tstr, event_type: tstr } subject-block = { agent_id: tstr, host_id: tstr } model-block = { boundary_type: tstr, claimed_level: WL }
; witness / seal / disclosure internal fields are refined by ; profiles; beyond the mandatory identifiers below they are open ; maps pending field-byte alignment. ; id identifies the witnessing component or system (opaque). witness-block = { id: tstr, * tstr => any } ; alg, sig, and kid are present iff the record is signed (CC2+); ; sig is base64url-encoded, no padding; kid is an opaque ; identifier of the signing key (resolution is out of scope). seal-block = { ? alg: tstr, ? sig: tstr, ? kid: tstr, * tstr => any } disclosure-block = { * tstr => any }
input-block = { arguments_hash_alg: hash-alg, arguments_hash: tstr, ; base64url, no padding * tstr => any } execution-block = { started_at: tdate, ended_at: tdate, outcome: tstr, result_hash_alg: hash-alg, result_hash: tstr ; base64url, no padding }
; Top-level typed evidence refs. Core verifies their PRESENCE and ; SYNTACTIC binding (digest + optional bound_record_id); ; it does not validate internal semantics of the referenced artifact. evidence-ref = { type: tstr, digest_alg: hash-alg, digest: tstr, ; base64url, no padding ? uri: tstr, ? bound_record_id: tstr, * tstr => any } evidence-block = { ; provenance is required for WL4; at WL5 it is optional ; unless a profile or policy requires it ? provenance: evidence-ref, ? independent_verification: evidence-ref, ; required for WL5 ? transparency: evidence-ref, ; orthogonal }
extensions-map = { * tstr => { critical: bool, value: any } }

figure.artwork:
if structure invalid:             reject(E_INVALID_SCHEMA)
if unknown critical extension:  reject(E_UNKNOWN_CRITICAL_EXTENSION)
if canonicalization fails:        reject(E_CANONICALIZATION_FAILED)
if timestamp invalid:             reject(E_TIMESTAMP_INVALID)
if boundary_type unregistered:    reject(E_UNKNOWN_BOUNDARY_TYPE)

; signature: absence is not an error (it caps the effective CC
; for this record); a present-but-invalid signature is rejected.
if seal.sig present:
    if seal.alg absent/unsupported: reject(E_UNSUPPORTED_ALGORITHM)
    if signature invalid:              reject(E_INVALID_SIGNATURE)
    if key binding fails:              reject(E_KEY_BINDING_FAILED)
    signed = true
else:
    signed = false

cc = resolve(capabilities_ref)        ; implementation-scoped CC
if cc unresolved or not accepted: cc = CC0  ; E_MISSING_CAPABILITIES
; a record without a valid signature is evaluated at most as
; CC1 (this record only)
effective_cc = cc if signed else min(cc, CC1)

base = min( claimed_level,
            attainable(boundary_type, claimed_level, evidence),
            maxCapability(effective_cc) )
if recorder qualification asserted:
    base = min( base, max_assurance(qualification_profile) )
verified_level = base
if a chain is supplied:
    verified_level = min( verified_level,
                       min over segments( segment.verified_level ) )

if verified_level == claimed_level: accept
else:                               downgrade
